mapper.select:
SELECT ter.id, ter.department_code, ter.emp_id, ter.emp_name, ter.request_date, ter.approval_status, SUM(CASE WHEN ted.transport_expense_type = 1 THEN ted.transport_amount ELSE 0 END) AS regular_transport_amount, SUM(CASE WHEN ted.transport_expense_type = 2 THEN ted.transport_amount ELSE 0 END) AS nonregular_transport_amount, SUM(ted.other_amount) AS other_expense_amount,
SUM(CASE WHEN ted.transport_expense_type = 1 THEN ted.transport_amount ELSE 0 END) + SUM(CASE WHEN ted.transport_expense_type = 2 THEN ted.transport_amount ELSE 0 END) + SUM(ted.other_amount) AS total_amount, ter.remarks, ter.create_user_id, ter.update_user_id, ter.create_time, ter.update_time, ter.del_flg, ter.picture_url FROM trx_expense_request AS ter LEFT JOIN trx_expense_detail AS ted ON ter.id = ted.request_id LEFT JOIN mst_department AS mst_department ON ter.department_code = mst_department.department_code
ter.del_flg != 1
AND mst_department.department_name = #{department}
AND ter.emp_name = #{employeeName}
AND ter.emp_id = #{employeeId}
AND ter.request_date >= STR_TO_DATE(CONCAT(#{startMonth}, '-01'), '%Y-%m-%d')
AND ter.request_date <= LAST_DAY(STR_TO_DATE(CONCAT(#{endMonth}, '-01'), '%Y-%m-%d'))
GROUP BY ter.id

